"""Migration of the Meridian CRM 4.2 nightly credit-hold sweep."""

from decimal import Decimal
from typing import Any


_ZERO = Decimal("0")
_EIGHT_TENTHS = Decimal("0.8")


def _numeric(value: Any) -> Decimal:
    """Apply legacy NVL/numeric-context handling for numeric input values."""
    if value is None:
        return _ZERO
    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return _ZERO
    return Decimal(str(value))


def _primary_key_value(row: dict, column: str) -> str:
    """Use the legacy character-key ordering used by the exported row data."""
    value = row.get(column, "")
    return "" if value is None else str(value)


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    """Run the nightly credit-hold sweep without mutating the supplied rows."""
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    # CRMScript FOR EACH uses ascending primary-key order for live rows.
    ordered_accounts = sorted(
        enumerate(new_accounts),
        key=lambda item: _primary_key_value(item[1], "ACCT_ID"),
    )
    ordered_orders = sorted(
        orders,
        key=lambda order: _primary_key_value(order, "ORD_ID"),
    )

    for _, account in ordered_accounts:
        if account.get("DEL_FLG") == "Y" or account.get("ACCT_TYP") != "C":
            continue

        acct_id = account.get("ACCT_ID")
        exposure = _ZERO

        for order in ordered_orders:
            if (
                order.get("ACCT_ID") == acct_id
                and order.get("DEL_FLG") != "Y"
                and order.get("STAT_CD") == "I"
            ):
                exposure += _numeric(order.get("TOT_AMT"))

        credit_limit = _numeric(account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if exposure <= credit_limit * _EIGHT_TENTHS and account.get("CRED_HOLD") == "Y":
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
